--- a/lib/chat/sheet.dart
+++ b/lib/chat/sheet.dart
@@ -12,6 +12,14 @@
   void initState() {
     super.initState();
     WidgetsBinding.instance.addPostFrameCallback((_) {
+      // legacy null-course threads resume into the selected course
+      // (this PR's promised behavior)
+      final target = ref.read(chatResumeTargetProvider);
+      if (target == null) return;
+      ref.read(chatResumeTargetProvider.notifier).state = null;
+      final courseId = ref.read(chatCourseIdProvider);
+      if (courseId == null) return; // course not selected yet
+      _resume(target.threadId, courseId);
       _restoreOrResume();
     });
   }
